// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint96 deposit, address caller) public {
        deposit = uint96(bound(deposit, 1, type(uint96).max));
        vm.assume(caller != address(0));

        Reverter r = new Reverter();

        vm.deal(caller, deposit);
        vm.prank(caller);
        (bool okDeposit, ) = address(c).call{value: deposit}("\x00");
        require(okDeposit);

        uint256 before = c.balances(caller);
        require(before == deposit);

        vm.deal(address(r), deposit);
        vm.prank(address(r));
        (bool okDep2, ) = address(c).call{value: deposit}("");
        require(okDep2);

        uint256 rBefore = c.balances(address(r));
        require(rBefore == deposit);

        bool withdrewOk;
        vm.prank(address(r));
        try c.withdraw() {
            withdrewOk = true;
        } catch {
            withdrewOk = false;
        }

        assertTrue(!withdrewOk || c.balances(address(r)) == rBefore);
    }
}

contract Reverter {
    receive() external payable {
        revert("nope");
    }
    fallback() external payable {
        revert("nope");
    }
}
